from pathlib import Path
import json,unicodedata,hashlib
r=Path('work/constants-recovery/SFT/Chemistry');rows=[(i,chr(i).casefold()) for i in range(0x110000) if chr(i).casefold()!=chr(i)];q=lambda s:json.dumps(s,ensure_ascii=False)
s='import SFT.Host.Text\nset_option maxRecDepth 10000\nnamespace SFT.Chemistry.SourceText\ndef foldTable : List (Nat × String) := ['+','.join('('+str(i)+','+q(x)+')' for i,x in rows)+']\n\ndef foldedChar (c : Char) : String :=\n match foldTable.find? (fun row => row.1 == c.toNat) with\n | some row => row.2\n | none => String.ofList [c]\n\ndef casefold (s : String) : String := SFT.Host.Text.join ((SFT.Host.Text.chars s).map foldedChar)\n\ndef whitespace (c : Char) : Bool :=\n ['+','.join(str(i) for i in range(0x110000) if chr(i).isspace())+'].contains c.toNat\n\ndef nonblank (s : String) : Bool := (SFT.Host.Text.chars s).any (fun c => !whitespace c)\nend SFT.Chemistry.SourceText\n';(r/'SourceText.lean').write_text(s);Path('work/chemistry555_casefold_source.json').write_text(json.dumps({'unicode_version':unicodedata.unidata_version,'nonidentity_rows':len(rows),'lean_sha256':hashlib.sha256(s.encode()).hexdigest(),'source_operation':'Python str.casefold and str.strip nonblank predicate used by chemistry/generated_law.py'},indent=2))
